/**
 * Hit stop: a few frames where the simulation holds still on a solid hit.
 *
 * This is the cheapest weight a melee game can buy — the pause is what makes a
 * swing feel like it connected with something rather than passed through it.
 *
 * Deliberately presentation-only. It scales the delta the *scene* integrates,
 * never the seeded run logic, so a stutter cannot change what a seed produces.
 * It is also capped hard: a long freeze reads as a dropped frame, not impact.
 */

import { MAX_IMPACT_HITSTOP_SECONDS } from './impact'

/**
 * Anything longer than this stops reading as impact and starts reading as lag.
 *
 * It sits at the top of the window `impact.ts` grades hits into. It used to be
 * 0.09, which was below the boss-kill request — so a boss kill, a trash kill,
 * and a room-wide overload all clipped to the same length and felt identical.
 */
const MAX_HITSTOP_SECONDS = MAX_IMPACT_HITSTOP_SECONDS

let remaining = 0
let frameScale = 1

/** Requests a hold. Overlapping hits take the longest, they do not accumulate. */
export function requestHitstop(seconds: number): void {
  if (!Number.isFinite(seconds) || seconds <= 0) return
  remaining = Math.min(MAX_HITSTOP_SECONDS, Math.max(remaining, seconds))
}

/**
 * Freeze presentation completely while the raw/UI clock continues to drain
 * the hold. A partial scale let physics and projectiles slide through hits.
 */
const HELD_TIME_SCALE = 0

/**
 * Latches this frame's presentation scale, then advances the raw hold clock.
 * MUST be called exactly once at the start of each frame.
 *
 * Consumption is deliberately separate from the query below, because every
 * enemy scales its own delta — draining the hold inside that call would end it
 * N times faster with N enemies on screen, so a crowd would feel no impact at
 * all while a lone target felt plenty.
 */
export function tickHitstop(deltaSeconds: number): void {
  frameScale = remaining > 0 ? HELD_TIME_SCALE : 1
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0 || remaining <= 0)
    return
  remaining = Math.max(0, remaining - deltaSeconds)
}

/** Time scale for this frame. Safe to call any number of times. */
export function hitstopScale(): number {
  return frameScale
}

/** Convenience for callers that just want their delta scaled. */
export function applyHitstop(deltaSeconds: number): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return 0
  return deltaSeconds * hitstopScale()
}

export function isHitstopActive(): boolean {
  return remaining > 0
}

export function resetHitstop(): void {
  remaining = 0
  frameScale = 1
}
