/**
 * Impact profiles: how hard a hit should *feel*.
 *
 * The scene already owned every ingredient of a good hit — hitstop, camera
 * trauma, camera kick, knockback, a hit flash — but each one was a constant.
 * A 15HP thrall and a 58HP brute were knocked back the same distance, and a
 * trash kill, a boss kill, and a room-wide overload all requested more hold
 * than the 0.09s cap allowed, so they arrived identical. Every switch was on
 * or off; none of them were dials.
 *
 * This module turns them into dials. It is deliberately pure: no Three.js, no
 * store, no time. Callers read a profile and apply it, which means the whole
 * feel of combat is unit-testable and tunable from one file.
 *
 * Hold durations stay inside the 40-80ms window that reads as impact, with the
 * ceiling reserved for a boss kill. Past ~130ms a hold stops reading as weight
 * and starts reading as a dropped frame.
 */

/** The heaviest hold in the game, spent only on a boss kill. */
export const MAX_IMPACT_HITSTOP_SECONDS = 0.13

/** The lightest hold that still registers as a hit rather than a hiccup. */
const MIN_IMPACT_HITSTOP_SECONDS = 0.03

/**
 * The roster's health range, used to place a target on a weight scale.
 * Blind thrall sits at the floor, crypt brute at the ceiling; bosses are off
 * the scale entirely and take their own branch.
 */
const LIGHTEST_ENEMY_HEALTH = 15
const HEAVIEST_ENEMY_HEALTH = 58

function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0
  return value < 0 ? 0 : value > 1 ? 1 : value
}

function positive(value: number, fallback: number): number {
  return Number.isFinite(value) && value > 0 ? value : fallback
}

/**
 * Where a target sits on the roster's weight scale, 0 (lightest) to 1
 * (heaviest). This is what separates swatting a thrall from felling a brute,
 * and it comes from max health rather than current health so a nearly-dead
 * brute still dies like a brute.
 */
export function targetWeight(maxHealth: number): number {
  const health = positive(maxHealth, LIGHTEST_ENEMY_HEALTH)
  return clamp01(
    (health - LIGHTEST_ENEMY_HEALTH) /
      (HEAVIEST_ENEMY_HEALTH - LIGHTEST_ENEMY_HEALTH),
  )
}

/**
 * How much of the target this hit erased, 0 to 1. Overkill clamps to 1 — once
 * a swing is lethal, more damage cannot make it feel more lethal.
 */
export function lethality(damage: number, targetMaxHealth: number): number {
  return clamp01(positive(damage, 0) / positive(targetMaxHealth, 1))
}

export interface SwingImpact {
  readonly hitstopSeconds: number
  readonly cameraTrauma: number
}

/**
 * The player's own swing. A whiff returns zeroes — trauma used to fire before
 * the hit test, so missing shook the camera exactly as hard as connecting and
 * the player got no feedback about which had happened.
 */
export function resolveSwingImpact({
  connected,
  baseHitstopSeconds,
  damageMultiplier = 1,
  targetsHit = 1,
}: {
  connected: boolean
  baseHitstopSeconds: number
  damageMultiplier?: number
  targetsHit?: number
}): SwingImpact {
  if (!connected) return { hitstopSeconds: 0, cameraTrauma: 0 }

  const boost = clamp01(positive(damageMultiplier, 1) - 1)
  // Cleaving three bodies should land heavier than clipping one, but the bonus
  // saturates fast so a crowded room does not become one long freeze.
  const crowd = Math.min(3, Math.max(0, Math.round(targetsHit) - 1))

  const hitstopSeconds = Math.min(
    0.11,
    Math.max(
      MIN_IMPACT_HITSTOP_SECONDS,
      positive(baseHitstopSeconds, MIN_IMPACT_HITSTOP_SECONDS) +
        boost * 0.05 +
        crowd * 0.008,
    ),
  )
  return {
    hitstopSeconds,
    cameraTrauma: Math.min(0.3, 0.14 + boost * 0.1 + crowd * 0.02),
  }
}

export interface HitImpact {
  readonly knockback: number
  readonly cameraTrauma: number
}

/**
 * A hit that did not kill. `pushStrength` is the attack's own shove — the
 * blade pushes less than an overload — and lethality scales it, so the same
 * swing sends a thrall flying and barely rocks a brute.
 */
export function resolveHitImpact({
  damage,
  targetMaxHealth,
  pushStrength,
}: {
  damage: number
  targetMaxHealth: number
  pushStrength: number
}): HitImpact {
  const share = lethality(damage, targetMaxHealth)
  return {
    knockback: positive(pushStrength, 0) * (0.45 + share * 0.9),
    cameraTrauma: 0.12 + share * 0.2,
  }
}

export interface KillImpact {
  readonly hitstopSeconds: number
  readonly cameraTrauma: number
  readonly cameraKick: number
}

/**
 * The paycheck moment. This is the only place allowed to spend the full hold,
 * and only for a boss — everything else is graded by the target's weight so
 * the player can hear the difference between clearing chaff and dropping the
 * thing that was actually threatening them.
 */
export function resolveKillImpact({
  targetMaxHealth,
  boss = false,
}: {
  targetMaxHealth: number
  boss?: boolean
}): KillImpact {
  if (boss) {
    return {
      hitstopSeconds: MAX_IMPACT_HITSTOP_SECONDS,
      cameraTrauma: 0.5,
      cameraKick: 0.85,
    }
  }
  const weight = targetWeight(targetMaxHealth)
  return {
    hitstopSeconds: 0.055 + weight * 0.055,
    cameraTrauma: 0.26 + weight * 0.16,
    cameraKick: 0.4 + weight * 0.28,
  }
}
